const tryLockRepoSession = `-- name: TryLockRepoSession :one
SELECT pg_try_advisory_lock(hashtextextended('erepo.repo:' || $1::uuid::text, 0))::bool AS locked
`

func (q *Queries) TryLockRepoSession(ctx context.Context, repoID uuid.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, tryLockRepoSession, repoID)
	var locked bool
	err := row.Scan(&locked)
	return locked, err
}

